//! Preflight against the protocol schema generated by the binary: a build whose schema lacks a
//! method the bridge needs is refused. Its own test binary (it sets an environment variable).

mod common;

#[test]
fn a_schema_without_a_required_method_is_refused() {
    std::env::set_var("IGNIS_FAKE_CODEX_SCHEMA", "old");
    let dir = tempfile::tempdir().unwrap();
    let e = ignis_research::runtime::preflight(&common::config(dir.path())).unwrap_err();
    assert!(e.contains("turn/interrupt"), "{e}");
}
